const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    // Northern part of Madagascar: latitude -12 to -15. Longitude range for Madagascar ~43 to 51.
    const geometry = ee.Geometry.Rectangle([43, -15, 51, -12]); // [west, south, east, north]
    const scale = 5000; // Use a reasonable scale to avoid timeouts for reduceRegion

    // Define the specific period (Dec 2018 - Jan 2019)
    const specificStart = '2018-12-01';
    const specificEnd = '2019-02-01'; // Up to but not including Feb 1st, covers Dec and Jan

    // Define the long-term average period (Dec-Jan from 2000-2019)
    const longTermStartYear = 2000;
    const longTermEndYear = 2019;

    // 2. Data Acquisition
    // Using CHIRPS Monthly Precipitation data
    const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/P05/GLOBAL_MONTHLY')
      .filterBounds(geometry);

    // 2.1. Get specific period data
    let specificPeriodCollection = chirps.filterDate(specificStart, specificEnd);
    const specificPeriodSize = await specificPeriodCollection.size().getInfo();

    if (specificPeriodSize === 0) {
      console.log("No CHIRPS data found for the specific period (Dec 2018 - Jan 2019).");
      console.log("C1");
      return;
    }
    console.log(`Specific period images found: ${specificPeriodSize}`);

    // Sum precipitation for the specific period
    const specificPeriodTotalPrecip = specificPeriodCollection.sum();

    // Calculate mean precipitation over the geometry for the specific period
    const specificPrecipResult = await specificPeriodTotalPrecip.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('precipitation').getInfo();

    if (specificPrecipResult === null || isNaN(specificPrecipResult)) {
      console.log("Calculation failure for specific period precipitation.");
      console.log("C3");
      return;
    }
    console.log(`Specific Period (Dec 2018 - Jan 2019) Avg Rainfall: ${specificPrecipResult.toFixed(2)} mm`);

    // 2.2. Get long-term average data
    let annualDecJanTotals = ee.List([]);

    for (let year = longTermStartYear; year <= longTermEndYear; year++) {
      const start = ee.Date.fromYMD(year, 12, 1); // December of the current year
      const end = ee.Date.fromYMD(year + 1, 2, 1); // February 1st of next year (to include Jan)

      let annualCollection = chirps.filterDate(start, end);
      const annualCollectionSize = await annualCollection.size().getInfo();

      if (annualCollectionSize > 0) {
        const annualTotalPrecip = annualCollection.sum();
        const annualPrecipRegion = await annualTotalPrecip.reduceRegion({
          reducer: ee.Reducer.mean(),
          geometry: geometry,
          scale: scale,
          maxPixels: 1e9
        }).get('precipitation').getInfo();

        if (annualPrecipRegion !== null && !isNaN(annualPrecipRegion)) {
          annualDecJanTotals = annualDecJanTotals.add(annualPrecipRegion);
        } else {
          console.log(`Warning: Null or NaN value for ${year} Dec-Jan precipitation. Skipping.`);
        }
      } else {
        console.log(`Warning: No CHIRPS data for ${year} Dec-Jan. Skipping.`);
      }
    }

    const annualDecJanTotalsSize = await annualDecJanTotals.size().getInfo();
    if (annualDecJanTotalsSize === 0) {
      console.log("No valid long-term average data could be computed (all years resulted in no data or null).");
      console.log("C2"); // Or C1 depending on if initial collection was empty
      return;
    }

    const longTermAverage = await annualDecJanTotals.reduce(ee.Reducer.mean()).getInfo();

    if (longTermAverage === null || isNaN(longTermAverage)) {
      console.log("Calculation failure for long-term average precipitation.");
      console.log("C3");
      return;
    }
    console.log(`Long-term average (Dec-Jan, 2000-2019) Rainfall: ${longTermAverage.toFixed(2)} mm`);
    console.log(`Number of years contributing to average: ${annualDecJanTotalsSize}`);


    // 5. Validation & Final Answer
    if (specificPrecipResult < longTermAverage) {
      console.log("A"); // Yes, it received less rain
    } else {
      console.log("B"); // No, it did not receive less rain
    }

  } catch (error) {
    console.error("An error occurred:", error);
    console.log("D"); // General error
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
